1	// create-extractor preprocessing — everything deterministic about turning an
2	// `extractor-request` issue into a branch an agent can write `extract()` on.
3	//
4	// The scheduler runs THIS FILE as a subprocess (cwd = this task dir, Action-side,
5	// bounded by `agent_preprocessing_timeout`) when the precondition found an
6	// eligible request. It absorbs what used to be four numbered scripts, a JSON
7	// hand-off through the agent, and a whole second workflow:
8	//
9	//   1. read the open `extractor-request` issues (bodies included — the scheduler's
10	//      `issues` signal deliberately carries none, so the precondition cannot and
11	//      must not triage);
12	//   2. triage each eligible one oldest-first (triage.js, over the committed
13	//      sources' real matches() + the popup's classifyHost) and CLOSE every
14	//      deny/allow/duplicate with its canned message — no agent, no branch;
15	//   3. for the first request that genuinely needs an extractor: claim it
16	//      (`agent-running`, the scheduler's own label — no custom vocabulary here),
17	//      branch, scaffold, prove the offline baseline green, and commit;
18	//   4. RECORD THE PAGE through ScraperAPI directly. Preprocessing runs inside
19	//      Actions, where SCRAPER_API_KEY already lives (the task names it in
20	//      `required_secrets`, which the wiring converge stamps into the workflow).
21	//      The `fetch-page.yml` workflow existed solely to hold that secret for an
22	//      agent that couldn't — dispatch, poll, pull. Deleted; this is one fetch in
23	//      the same process that needs the bytes;
24	//   5. push, open the DRAFT PR the agent continues on, and request the agent
25	//      (CLAUDINITE_REQUEST_AGENT).
26	//
27	// A run that finds only closeable requests, or cannot record a page, requests NO
28	// agent — the hours where nothing needs judgment cost no model at all.
29	//
30	// Almost no code→agent data channel (agent-preprocessing DESIGN §3): everything the
31	// agent needs is IN THE REPO — the pushed branch, its scaffold, the recorded page. The
32	// one exception §3 names is the IDENTITY of what this run created: the branch and
33	// draft-PR number ride the agent-request file into the dispatch issue.
34	//
35	// Exit codes are the task's contract: 0 = handled (with or without an agent),
36	// non-zero = the task FAILED and the scheduler converges it to `needs-human`. A
37	// request we deliberately hand to a human (unfetchable page) is a 0 — it is a
38	// correct outcome, not a broken run.
39	
40	import { execFileSync } from 'node:child_process';
41	import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync } from 'node:fs';
42	import { join } from 'node:path';
43	import { createRequire } from 'node:module';
44	import { pathToFileURL } from 'node:url';
45	import { recordPage } from './scraperapi.mjs';
46	
47	const require = createRequire(import.meta.url);
48	const { runTriage } = require('./triage.js');
49	const { addSample } = require('./attach-sample-url.js');
50	
51	const API = 'https://api.github.com';
52	// `extractor-request` marks the issue KIND (the form applies it; it stays for the
53	// issue's life). Its STATE uses the scheduler's own labels rather than any
54	// invented here — the scheduler guarantees they exist before preprocessing runs,
55	// so nothing below has to create them:
56	//   agent-running — this pipeline owns the request (from claim until its PR lands)
57	//   needs-human   — handed over; the pipeline will not pick it up again
58	// `ready-for-agent` is never applied to a request: it is the executor's trigger.
59	const REQUEST_LABEL = 'extractor-request';
60	const CLAIMED_LABEL = 'agent-running';
61	const BLOCKED_LABEL = 'needs-human';
62	const BRANCH_PREFIX = 'claude/extractor/';
63	const RECORD_PREFIX = 'claude/record-pages';
64	const DATA_DIR = 'dev/requirements/extractor/data/server-fetched';
65	
66	// How long a claimed request with nothing to show for it may sit before this
67	// pipeline releases it. The executor's stale-`agent-running` sweep covers dispatch
68	// issues only (it cannot know that a request stays claimed while its PR is in
69	// review), so releasing our OWN stale claims is this worker's job.
70	const STALE_CLAIM_MS = 6 * 60 * 60 * 1000;
71	
72	// --- pure helpers (unit-tested; no I/O) --------------------------------------
73	
74	// The requests this run may act on, oldest first. Mirrors the precondition's
75	// eligibility exactly so the gate and the worker can never disagree about what
76	// "eligible" means — the worker re-derives it from full issue objects rather than
77	// trusting the gate's older snapshot.
78	export const labelsOf = (i) => (i.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name ?? ''));
79	
80	export function eligible(issues) {
81	  return (issues ?? [])
82	    .filter((i) => !i.pull_request)
83	    .filter((i) => {
84	      const labels = labelsOf(i);
85	      return labels.includes(REQUEST_LABEL)
86	        && !labels.includes(BLOCKED_LABEL)
87	        && !labels.includes(CLAIMED_LABEL);
88	    })
89	    .sort((a, b) => a.number - b.number);
90	}
91	
92	// Claimed requests whose claim is stale: nothing this pipeline produced is still
93	// open for them (no `claude/extractor/*` PR says `Closes #N`) and the issue has
94	// been quiet past the grace period — so a run died between claiming and delivering.
95	// Releasing the claim makes them eligible again next hour. `openPrs` is the repo's
96	// open PRs; `now` is passed in so this is pure.
97	export function staleClaims(issues, openPrs, now) {
98	  const claimedByPr = new Set(
99	    (openPrs ?? [])
100	      .filter((pr) => String(pr?.head?.ref ?? '').startsWith(BRANCH_PREFIX))
101	      .flatMap((pr) => [...String(pr?.body ?? '').matchAll(/\bCloses #(\d+)/gi)].map((m) => Number(m[1]))),
102	  );
103	  return (issues ?? [])
104	    .filter((i) => (i.labels ?? []).some((l) => (typeof l === 'string' ? l : l?.name) === CLAIMED_LABEL))
105	    .filter((i) => !claimedByPr.has(i.number))
106	    .filter((i) => now - new Date(i.updated_at ?? 0).getTime() > STALE_CLAIM_MS)
107	    .map((i) => i.number);
108	}
109	
110	// --- the pending-page sweep (was the record-page task) ------------------------
111	// A `.url` with no `.html` beside it is a case whose page is missing, which keeps
112	// `test:live` red until someone records it. Only gardening produces that state — a
113	// maintainer re-points a taken-down event and deletes the stale page — because a
114	// full pipeline run always writes the two together. It is a handful of lines over
115	// the recorder this file already owns, so it lives here rather than in a task of
116	// its own.
117	
118	// The case names needing a record. `entries` is a directory listing; `has` answers
119	// "is this file present".
120	export function pendingCases(entries, has) {
121	  return entries
122	    .filter((f) => f.endsWith('.url'))
123	    .map((f) => f.slice(0, -'.url'.length))
124	    .filter((name) => !has(`${name}.html`))
125	    .sort();
126	}
127	
128	// The head branch of the sweep's open PR, found by prefix, so repeated runs
129	// accumulate onto one PR instead of opening a new one each time. null → mint one.
130	export function openFamilyBranch(pulls, prefix = RECORD_PREFIX) {
131	  const pr = (pulls ?? []).find((p) => String(p?.head?.ref ?? '').startsWith(prefix));
132	  return pr ? pr.head.ref : null;
133	}
134	
135	// A page fetch retries a transient 5xx (scraperapi.mjs), so a backlog can outlast
136	// `agent_preprocessing_timeout` — a hard SIGKILL that would land mid-loop and throw
137	// away pages already recorded, since the commit comes after the loop. So only START
138	// a fetch while a worst case still fits with room to deliver; anything skipped
139	// keeps no `.html` and is picked up next run.
140	//
141	// worstCaseFetchMs: recordPage's 4 attempts x 120s + ~50s of backoff.
142	export function hasRoomToStart(elapsedMs, budgetMs, worstCaseFetchMs = 530_000, deliveryMs = 60_000) {
143	  return elapsedMs + worstCaseFetchMs + deliveryMs <= budgetMs;
144	}
145	
146	// The PR title for a finished run, by mode — the same two phrasings the routine
147	// spec used to ask the agent to write by hand.
148	export function prTitle(mode, host, sourceBase) {
149	  return mode === 'supported'
150	    ? `Add an integration case for ${host} (hardens ${sourceBase})`
151	    : `Implement the extractor for ${host}`;
152	}
153	
154	// --- I/O shell ---------------------------------------------------------------
155	
156	const run = (cmd, args, opts = {}) =>
157	  execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
158	
159	let ROOT;
160	let REPO;
161	let TOKEN;
162	
163	const git = (...args) => run('git', ['-C', ROOT, ...args]);
164	const npm = (...args) => run(process.platform === 'win32' ? 'npm.cmd' : 'npm', args, { cwd: ROOT, stdio: ['ignore', 'inherit', 'inherit'] });
165	
166	async function gh(path, { method = 'GET', body } = {}) {
167	  const res = await fetch(`${API}${path}`, {
168	    method,
169	    headers: {
170	      authorization: `Bearer ${TOKEN}`,
171	      accept: 'application/vnd.github+json',
172	      'x-github-api-version': '2022-11-28',
173	      ...(body ? { 'content-type': 'application/json' } : {}),
174	    },
175	    body: body ? JSON.stringify(body) : undefined,
176	  });
177	  let json = null;
178	  try { json = await res.json(); } catch { /* empty body */ }
179	  return { status: res.status, json };
180	}
181	
182	const comment = (n, text) => gh(`/repos/${REPO}/issues/${n}/comments`, { method: 'POST', body: { body: text } });
183	
184	const addLabel = (n, name) => gh(`/repos/${REPO}/issues/${n}/labels`, { method: 'POST', body: { labels: [name] } });
185	const removeLabel = (n, name) => gh(`/repos/${REPO}/issues/${n}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' });
186	const closeNotPlanned = (n) => gh(`/repos/${REPO}/issues/${n}`, { method: 'PATCH', body: { state: 'closed', state_reason: 'not_planned' } });
187	
188	// Every open issue carrying the request label, bodies included. The scheduler's
189	// `issues` signal drops bodies (they would bloat every task's collection), which is
190	// precisely why triage cannot live in the precondition.
191	async function openRequests() {
192	  const out = [];
193	  for (let page = 1; ; page += 1) {
194	    const { status, json } = await gh(`/repos/${REPO}/issues?state=open&labels=${REQUEST_LABEL}&per_page=100&page=${page}`);
195	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
196	    out.push(...json);
197	    if (json.length < 100) break;
198	  }
199	  return out;
200	}
201	
202	// Close a request that needs no extractor, with triage's canned message. `sample`
203	// additionally folds this page into the leader issue as an extra sample page, so a
204	// duplicate request's URL is banked rather than discarded.
205	async function closeSkipped(issue, decision) {
206	  if (decision.reason === 'sample' && decision.duplicateOf) {
207	    const { status, json: leader } = await gh(`/repos/${REPO}/issues/${decision.duplicateOf}`);
208	    if (status === 200) {
209	      const body = addSample(leader.body ?? '', decision.url);
210	      if (body !== (leader.body ?? '')) {
211	        await gh(`/repos/${REPO}/issues/${decision.duplicateOf}`, { method: 'PATCH', body: { body } });
212	      }
213	    }
214	  }
215	  await comment(issue.number, decision.message);
216	  await closeNotPlanned(issue.number);
217	  console.log(`create-extractor: closed #${issue.number} (${decision.reason})`);
218	}
219	
220	// Hand a request to a human: say what went wrong on the issue, label it, and
221	// release the claim. Never a task failure — the pipeline correctly declining a page
222	// is a normal outcome.
223	async function handToHuman(number, why) {
224	  await comment(number, why);
225	  await addLabel(number, BLOCKED_LABEL);
226	  await removeLabel(number, CLAIMED_LABEL);
227	  console.log(`create-extractor: handed #${number} to a human — ${why}`);
228	}
229	
230	// Branch, scaffold, prove the offline baseline green, and commit — the old
231	// 3-prepare.sh, minus the .url-only fetch dance. The offline suite does not read
232	// the recorded page (it runs on synthetic HTML), so proving green BEFORE the fetch
233	// is correct and keeps a bad scaffold from burning a ScraperAPI call.
234	function scaffold(decision) {
235	  git('checkout', '-B', decision.branch);
236	  const data = join(ROOT, DATA_DIR);
237	  mkdirSync(data, { recursive: true });
238	  // The .url is the single source of truth for the page's URL (live.test.js reads
239	  // it to set the DOM origin).
240	  writeFileSync(join(data, `${decision.caseName}.url`), decision.url);
241	
242	  if (decision.mode === 'supported') {
243	    run(process.execPath, [join(import.meta.dirname, 'scaffold.js'), 'supported', decision.caseName, decision.host], { cwd: ROOT });
244	  } else {
245	    run(process.execPath, [join(import.meta.dirname, 'scaffold.js'), 'new', decision.caseName, decision.host, decision.url], { cwd: ROOT });
246	    npm('run', 'index');
247	  }
248	  npm('run', 'test:offline');
249	}
250	
251	function commitAll(message) {
252	  git('add', '-A');
253	  git('-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com', 'commit', '-m', message);
254	}
255	
256	// Push, retrying transient network failures on the same 0/2/4/8/16s back-off
257	// 3-prepare.sh used. A push that fails once here would otherwise throw away a
258	// scaffold, an offline-suite run and a paid page fetch.
259	function push(branch, waitMs = [2000, 4000, 8000, 16000]) {
260	  const remote = `https://x-access-token:${TOKEN}@github.com/${REPO}.git`;
261	  for (let attempt = 0; ; attempt += 1) {
262	    try {
263	      git('push', '--force', remote, `HEAD:refs/heads/${branch}`);
264	      return;
265	    } catch (e) {
266	      if (attempt >= waitMs.length) throw e;
267	      execFileSync(process.execPath, ['-e', `setTimeout(()=>{}, ${waitMs[attempt]})`]);
268	    }
269	  }
270	}
271	
272	// The draft PR the agent continues on. Its number reaches the agent through the dispatch
273	// issue (the handoff at the foot of main); the `claude/extractor/` prefix is this task's
274	// own bookkeeping for reclaiming stale requests. DRAFT because the extractor is not
275	// written yet; the agent marks it ready when the postconditions pass.
276	async function openDraftPr(decision, base, issueNumber) {
277	  const body = [
278	    `Closes #${issueNumber}`,
279	    '',
280	    `Automated extractor pipeline for \`${decision.host}\` (${decision.mode === 'supported' ? 'adds an integration case to an existing source' : 'new source'}).`,
281	    '',
282	    'Scaffold, the recorded page, and a green offline baseline were prepared deterministically by the',
283	    '`gcec/create-extractor` task\'s preprocessing. The extractor implementation and the case values are',
284	    'the agent stage\'s work; this PR is a draft until they land and its postconditions pass.',
285	  ].join('\n');
286	  const { status, json } = await gh(`/repos/${REPO}/pulls`, {
287	    method: 'POST',
288	    body: { head: decision.branch, base, title: prTitle(decision.mode, decision.host, decision.sourceBase), body, draft: true },
289	  });
290	  if (status >= 300) throw new Error(`could not open the draft PR: ${status} ${JSON.stringify(json?.errors ?? json?.message ?? '')}`);
291	  return json.number;
292	}
293	
294	// Record every case whose `.url` is committed but whose `.html` is not, and deliver
295	// them on the sweep's own branch/PR (separate from any extractor PR — a missing page
296	// is a repo-maintenance fix, not part of implementing a site). Returns the number
297	// recorded. A page that will not record does NOT sink the run: the others still
298	// land and the failure is reported in the PR body.
299	async function sweepPendingPages(key, base, budgetMs) {
300	  const dir = join(ROOT, DATA_DIR);
301	  if (!existsSync(dir)) return 0;
302	  const pending = pendingCases(readdirSync(dir), (f) => existsSync(join(dir, f)));
303	  if (!pending.length) return 0;
304	
305	  const { json: pulls } = await gh(`/repos/${REPO}/pulls?state=open&per_page=100`);
306	  const existing = openFamilyBranch(Array.isArray(pulls) ? pulls : []);
307	  const branch = existing ?? `${RECORD_PREFIX}-${new Date().toISOString().slice(0, 10)}`;
308	  git('checkout', '-B', branch);
309	
310	  const startedAt = Date.now();
311	  const recorded = [];
312	  const failed = [];
313	  const deferred = [];
314	  for (const name of pending) {
315	    // Always attempt the first: a budget too small for even one page is a
316	    // declaration bug, and failing loudly beats silently recording nothing.
317	    if (recorded.length + failed.length > 0 && !hasRoomToStart(Date.now() - startedAt, budgetMs)) {
318	      deferred.push(name);
319	      continue;
320	    }
321	    const url = readFileSync(join(dir, `${name}.url`), 'utf8').trim();
322	    try {
323	      const bytes = await recordPage(key, { url }, join(dir, `${name}.html`));
324	      recorded.push(name);
325	      console.log(`create-extractor: recorded ${bytes} bytes for the pending case ${name}`);
326	    } catch (e) {
327	      failed.push(`${name}: ${e.message}`);
328	      console.log(`! create-extractor: pending case ${name} — ${e.message}`);
329	    }
330	  }
331	  if (deferred.length) console.log(`create-extractor: ${deferred.length} pending page(s) left for the next run: ${deferred.join(', ')}`);
332	  if (!recorded.length) {
333	    git('checkout', base);
334	    console.log(`create-extractor: no pending page recorded (${failed.length} failed)`);
335	    return 0;
336	  }
337	
338	  git('add', '--', DATA_DIR);
339	  git('-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
340	    'commit', '-m', `chore: record ${recorded.length} cached event page(s) via ScraperAPI [skip ci]`);
341	  push(branch);
342	  if (!existing) {
343	    const body = [
344	      'Recorded the cached event page(s) for live cases whose `.url` is committed but whose page was not.',
345	      '',
346	      ...recorded.map((n) => `- \`${n}\``),
347	      ...(failed.length ? ['', 'Could not be recorded (re-point the `.url`, or drop the case):', ...failed.map((f) => `- ${f}`)] : []),
348	      '',
349	      'Filed by the `gcec/create-extractor` task. Merging this makes `test:live` green for these cases.',
350	    ].join('\n');
351	    const { status } = await gh(`/repos/${REPO}/pulls`, {
352	      method: 'POST', body: { head: branch, base, title: 'Record cached event pages', body },
353	    });
354	    if (status >= 300) throw new Error(`could not open the recorded-pages PR: ${status}`);
355	  }
